<script setup lang="ts">
import {ref,watch} from 'vue'
type Row=Record<string,any>
const props=defineProps<{modelValue:Row,kind:'basic'|'dns'}>()
const emit=defineEmits<{ 'update:modelValue':[Row] }>()
const advanced=ref(''),dirty=ref(false),error=ref('')
watch(()=>props.modelValue,()=>{if(!dirty.value)advanced.value=JSON.stringify(props.modelValue,null,2)},{immediate:true,deep:true})
function set(k:string,v:any){emit('update:modelValue',{...props.modelValue,[k]:v})}
function lines(k:string){return (props.modelValue[k]??[]).join('\n')}
function setLines(k:string,v:string){set(k,v.split(/\r?\n/).map(s=>s.trim()).filter(Boolean))}
function apply(){try{const v=JSON.parse(advanced.value);if(!v||Array.isArray(v)||typeof v!=='object')throw new Error('需要 JSON 对象');dirty.value=false;error.value='';emit('update:modelValue',v)}catch(e){error.value=String(e)}}
defineExpose({pending:dirty})
const dnsFields=[['nameserver','主要 DNS（每行一个，可用 #策略组）'],['default-nameserver','引导 DNS'],['proxy-server-nameserver','节点域名 DNS'],['direct-nameserver','直连 DNS'],['fallback','后备 DNS'],['fake-ip-filter','Fake IP 排除域名']]
</script>
<template><section class="panel section-options"><h3>{{kind==='basic'?'基础配置':'DNS 配置'}}</h3><p class="muted">{{kind==='basic'?'客户端本地端口、日志、IP 与运行选项；节点身份由订阅生成。':'独立配置解析服务器与 Fake IP，分享时按客户端能力转换。'}}</p><p v-if="dirty" class="notice">JSON 尚未应用，请先应用或取消 JSON 修改。</p><fieldset :disabled="dirty"><div class="fields" v-if="kind==='basic'"><label>本地混合端口<input type="number" min="1024" max="65535" :value="modelValue['mixed-port']??7890" @input="set('mixed-port',Number(($event.target as HTMLInputElement).value))"></label><label>运行模式<select :value="modelValue.mode??'rule'" @change="set('mode',($event.target as HTMLSelectElement).value)"><option>rule</option><option>global</option><option>direct</option></select></label><label>日志级别<select :value="modelValue['log-level']??'warning'" @change="set('log-level',($event.target as HTMLSelectElement).value)"><option>silent</option><option>error</option><option>warning</option><option>info</option><option>debug</option></select></label><label>控制器（仅回环）<input :value="modelValue['external-controller']??''" placeholder="127.0.0.1:9090" @change="set('external-controller',($event.target as HTMLInputElement).value)"></label></div><div class="fields" v-else><label>DNS 模式<select :value="modelValue['enhanced-mode']??'redir-host'" @change="set('enhanced-mode',($event.target as HTMLSelectElement).value)"><option>fake-ip</option><option>redir-host</option></select></label><label>本地 DNS 监听<input :value="modelValue.listen??'127.0.0.1:1053'" @change="set('listen',($event.target as HTMLInputElement).value)"></label><label>Fake IP 网段<input :value="modelValue['fake-ip-range']??'198.18.0.1/16'" @change="set('fake-ip-range',($event.target as HTMLInputElement).value)"></label></div><div class="choice-list"><label v-for="[key,label] in kind==='basic'?[['ipv6','客户端 IPv6'],['allow-lan','允许局域网代理连接'],['unified-delay','统一延迟'],['tcp-concurrent','TCP 并发']]:[['enable','启用 DNS'],['ipv6','DNS IPv6'],['respect-rules','DNS 遵守路由规则'],['prefer-h3','优先 HTTP/3']]" :key="key"><input type="checkbox" :checked="!!modelValue[key!]" @change="set(key!,($event.target as HTMLInputElement).checked)">{{label}}</label></div><div class="dns-grid" v-if="kind==='dns'"><label v-for="[key,label] in dnsFields" :key="key">{{label}}<textarea :aria-label="label" :value="lines(key!)" rows="4" @input="setLines(key!,($event.target as HTMLTextAreaElement).value)"></textarea></label></div></fieldset><details><summary>{{kind==='basic'?'TUN、嗅探及其他基础字段':'DNS 策略和其他字段'}} · 手动 JSON</summary><textarea aria-label="分区 JSON" v-model="advanced" @input="dirty=true" rows="16" spellcheck="false" class="native-preview"></textarea><p v-if="error" role="alert" class="error">{{error}}</p><div class="row-actions"><button type="button" class="secondary" @click="apply">应用分区 JSON</button><button type="button" class="secondary" @click="dirty=false;advanced=JSON.stringify(modelValue,null,2);error=''">取消 JSON 修改</button></div></details></section></template>
<style scoped>fieldset{border:0;padding:0;margin:0;min-width:0}.section-options{margin:14px 0}.dns-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.choice-list{margin:18px 0}@media(max-width:700px){.dns-grid{grid-template-columns:1fr}}</style>
